content.query:
let sessions = customMetrics | where timestamp {TimeRange} | where "{Version:label}" == "All" or application_Version in ({Version}) | where name == "clubhouse.app.sessions" | summarize s = sum(value) by day = bin(timestamp, 1d);
let unclean = customMetrics | where timestamp {TimeRange} | where "{Version:label}" == "All" or application_Version in ({Version}) | where name == "clubhouse.app.unclean_exits" | summarize u = sum(value) by day = bin(timestamp, 1d);
sessions
| join kind=leftouter unclean on day
| project day, crash_free_pct = round(100.0 * (s - coalesce(u, 0.0)) / s, 1)

let checks = customMetrics | where timestamp {TimeRange} | where "{Version:label}" == "All" or application_Version in ({Version}) | where name == "clubhouse.update.checks" | summarize n = sum(value) by stage = strcat("check: ", tostring(customDimensions["clubhouse.update.result"]));
let applies = requests | where timestamp {TimeRange} | where "{Version:label}" == "All" or application_Version in ({Version}) | where name == "clubhouse.update.apply" | summarize n = todouble(sum(itemCount)) by stage = strcat("apply: ", tostring(customDimensions["clubhouse.update.result"]));
let verified = customEvents | where timestamp {TimeRange} | where "{Version:label}" == "All" or application_Version in ({Version}) | where name == "clubhouse.update.apply_verified" | summarize n = todouble(sum(itemCount)) by stage = strcat("verified: ", tostring(customDimensions["clubhouse.update.apply.verified"]));
union checks, applies, verified
| order by stage asc
